bool vcardparameter_kind_is_valid(const vcardparameter_kind kind)
{
    int i = 0;
    int num_params = (int)(sizeof(parameter_map) / sizeof(parameter_map[0]));

    if (kind == VCARD_ANY_PARAMETER) {
        return false;
    }

    num_params--;
    do {
        if (parameter_map[i].kind == kind) {
            return true;
        }
    } while (i++ < num_params);

    return false;
}

